package com.freshmart.catalog;
import org.apache.ibatis.annotations.*;import java.time.Instant;import java.util.List;
@Mapper
public interface CatalogMapper {
 String COLUMNS="p.product_id,p.spu_code,p.category_id,p.name,p.description,p.origin,p.storage,p.image_url,p.status,p.version";
 String FILTER="p.status='ON_SALE' AND EXISTS(SELECT 1 FROM fm_category c WHERE c.category_id=p.category_id AND c.enabled=true) AND EXISTS(SELECT 1 FROM fm_sku s WHERE s.product_id=p.product_id AND s.status='ACTIVE') <if test='categoryId!=null'>AND p.category_id=#{categoryId}</if><if test='keyword!=null'>AND LOCATE(#{keyword},p.name)&gt;0</if><if test='nearExpiry'>AND EXISTS(SELECT 1 FROM fm_sku s JOIN fm_inventory_batch b ON b.sku_id=s.sku_id WHERE s.product_id=p.product_id AND s.status='ACTIVE' AND b.lifecycle_status='NORMAL' AND b.on_hand-b.reserved-b.quarantined&gt;0 AND b.expires_at&gt;#{now} AND b.expires_at&lt;=#{nearAt})</if>";
 String SORT_PRICE="(SELECT MIN(CASE WHEN EXISTS(SELECT 1 FROM fm_inventory_batch b WHERE b.sku_id=s.sku_id AND b.lifecycle_status='NORMAL' AND b.on_hand-b.reserved-b.quarantined&gt;0 AND b.expires_at&gt;#{now} AND b.expires_at&lt;=#{nearAt}) THEN LEAST(s.member_price,FLOOR((CAST(s.price AS DECIMAL(30,0))*#{discountBps}+5000)/10000)) ELSE s.member_price END) FROM fm_sku s WHERE s.product_id=p.product_id AND s.status='ACTIVE')";
 @Select("SELECT category_id,code,name,short_name,image_url,sort_order,enabled FROM fm_category WHERE enabled=true ORDER BY sort_order,category_id") List<CategoryRow> categories();
 @Select("<script>SELECT COUNT(*) FROM fm_product p WHERE "+FILTER+"</script>") long count(@Param("categoryId")String categoryId,@Param("keyword")String keyword,@Param("nearExpiry")boolean nearExpiry,@Param("now")Instant now,@Param("nearAt")Instant nearAt);
 @Select("<script>SELECT "+COLUMNS+" FROM fm_product p WHERE "+FILTER+" ORDER BY <choose><when test=\"sort=='PRICE_ASC'\">"+SORT_PRICE+" ASC,</when><when test=\"sort=='PRICE_DESC'\">"+SORT_PRICE+" DESC,</when></choose>p.product_id ASC LIMIT #{size} OFFSET #{offset}</script>") List<ProductRow> products(@Param("categoryId")String categoryId,@Param("keyword")String keyword,@Param("nearExpiry")boolean nearExpiry,@Param("sort")String sort,@Param("now")Instant now,@Param("nearAt")Instant nearAt,@Param("discountBps")int discountBps,@Param("size")int size,@Param("offset")long offset);
 @Select("SELECT "+COLUMNS+" FROM fm_product p JOIN fm_category c ON c.category_id=p.category_id WHERE p.product_id=#{id} AND p.status='ON_SALE' AND c.enabled=true") ProductRow product(String id);
 @Select("<script>SELECT sku_id,sku_code,product_id,name,unit_label,base_unit,price_mode,price_unit_gram,price,member_price,image_url,status,version FROM fm_sku WHERE status='ACTIVE' AND product_id IN <foreach collection='ids' item='id' open='(' separator=',' close=')'>#{id}</foreach> ORDER BY sku_id</script>") List<SkuRow> skus(@Param("ids")List<String> ids);
 @Select("<script>SELECT sku_id,on_hand-reserved-quarantined AS available,received_at,expires_at FROM fm_inventory_batch WHERE lifecycle_status='NORMAL' AND expires_at&gt;#{now} AND on_hand-reserved-quarantined&gt;0 AND sku_id IN <foreach collection='ids' item='id' open='(' separator=',' close=')'>#{id}</foreach> ORDER BY expires_at,batch_id</script>") List<CatalogBatchRow> availableBatches(@Param("ids")List<String>ids,@Param("now")Instant now);
}
